//! 🌈️ Borrowed color and function cells follow authored scalar and sequence tables.
use super::*;
pub(super) fn reals(c:&mut Census<'_,'_>,table:&str,role:&str,v:&D)->Result<(),ValueError>{for value in list(v)?{c.row(table,&[Int,Text(role),Int,real(value)?])?;}Ok(())}
pub(super) fn sequence(c:&mut Census<'_,'_>,table:&str,v:&D)->Result<(),ValueError>{for value in list(v)?{c.row(table,&[Int,Int,real(value)?])?;}Ok(())}
pub(super) fn function(c:&mut Census<'_,'_>,v:&D)->Result<(),ValueError>{
 if c.depth>=64{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"PDF borrowed semantic containment depth exceeded"))}c.depth+=1;let result=(||{
 let tag=kind(v)?;let mut f=[Null;8];
 match tag{"sampled"=>{f[1]=Int;f[2]=Int;f[3]=Int;f[4]=integer(field(v,"order")?)?;f[6]=c.blob(field(v,"samples")?)?;},"exponential"=>{f[0]=Int;f[5]=real(field(v,"n")?)?;},"stitching"=>f[0]=Int,"postScript"=>f[7]=Text(text(field(v,"code")?)?),"array"=>{},_=>return Err(invalid())}
 let mut cells=vec![Text(tag)];cells.extend(f);c.row("pdf_function",&cells)?;
 for role in match tag{"sampled"=>&["domain","range","encode","decode"][..],"exponential"=>&["domain","range","c0","c1"],"stitching"=>&["domain","range","bounds","encode"],"postScript"=>&["domain","range"],_=>&[]}{reals(c,"pdf_function_real",role,field(v,role)?)?;}
 if tag=="sampled"{for value in list(field(v,"size")?)?{c.row("pdf_function_size",&[Int,Int,integer(value)?])?;}}
 if matches!(tag,"array"|"stitching"){for child in list(field(v,"functions")?)?{function(c,child)?;c.relation("pdf_function_child")?;}}Ok(())
})();c.depth-=1;result
}
pub(super) fn color(c:&mut Census<'_,'_>,v:&D)->Result<(),ValueError>{
 if c.depth>=64{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"PDF borrowed semantic containment depth exceeded"))}c.depth+=1;let result=(||{
 let tag=kind(v)?;let mut f=[Null;12];
 match tag{
 "deviceGray"|"deviceRgb"|"deviceCmyk"=>{},
 "calGray"=>{f[9]=Int;f[10]=Int;},
 "calRgb"=>{f[9]=Int;f[10]=Int;f[11]=Int;},
 "lab"=>{f[9]=Int;f[8]=Int;},
 "iccBased"=>{f[0]=integer(field(v,"components")?)?;f[1]=c.blob(field(v,"profile")?)?;f[8]=Int;},
 "indexed"=>{f[2]=Int;f[3]=c.blob(field(v,"lookup")?)?;},
 "separation"=>{f[4]=Text(text(field(v,"name")?)?);function(c,field(v,"tintTransform")?)?;f[6]=Int;},
 "deviceN"=>{function(c,field(v,"tintTransform")?)?;f[6]=Int;let a=field(v,"attributes")?;if !matches!(a,D::Null){objects::dictionary(c,a)?;f[7]=Int;}},
 "pattern"=>{},"named"=>f[4]=Text(text(field(v,"name")?)?),_=>return Err(invalid())
 }
 let child=match tag{"iccBased"|"separation"|"deviceN"=>field(v,"alternate")?,"indexed"|"pattern"=>field(v,"base")?,_=>&D::Null};
 if !matches!(child,D::Null){color(c,child)?;f[5]=Int;}
 let mut cells=vec![Text(tag)];cells.extend(f);c.row("pdf_color_space",&cells)?;
 for role in match tag{"calGray"=>&["whitePoint","blackPoint"][..],"calRgb"=>&["whitePoint","blackPoint","gamma","matrix"],"lab"=>&["whitePoint","blackPoint","range"],"iccBased"=>&["range"],_=>&[]}{reals(c,"pdf_color_real",role,field(v,role)?)?;}
 if tag=="calGray"{let gamma=field(v,"gamma")?;if !matches!(gamma,D::Null){c.row("pdf_color_real",&[Int,Text("gamma"),Int,real(gamma)?])?;}}
 if tag=="deviceN"{for name in list(field(v,"names")?)?{c.row("pdf_color_name",&[Int,Int,Text(text(name)?)])?;}}Ok(())
})();c.depth-=1;result
}
